/**
 * useCategories Hook Tests
 *
 * Tests for the custom useCategories hook that manages category CRUD operations.
 * This file tests fetching categories, creating categories, updating categories,
 * deleting categories, and toggling category visibility.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { renderHook, waitFor, act } from '@testing-library/react'
import { useCategories } from '@/hooks/useCategories'
import { createMockCategory } from '@/__tests__/fixtures/test-data'
import { createMockSupabaseClient } from '@/__tests__/mocks/supabase'

// Mock the Supabase client
vi.mock('@/lib/supabase/client', () => ({
  createClient: vi.fn(),
}))

// Import after mocking to get the mocked version
import { createClient } from '@/lib/supabase/client'

describe('useCategories Hook', () => {
  const mockOrganizationId = 'test-org-id'

  beforeEach(() => {
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  describe('Initial State', () => {
    it('should initialize with empty categories array', () => {
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const { result } = renderHook(() => useCategories(mockOrganizationId))

      expect(result.current.categories).toEqual([])
      expect(result.current.isLoading).toBe(false)
      expect(result.current.error).toBeNull()
    })

    it('should provide all CRUD methods', () => {
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const { result } = renderHook(() => useCategories(mockOrganizationId))

      expect(typeof result.current.fetchCategories).toBe('function')
      expect(typeof result.current.createCategory).toBe('function')
      expect(typeof result.current.updateCategory).toBe('function')
      expect(typeof result.current.deleteCategory).toBe('function')
      expect(typeof result.current.toggleVisibility).toBe('function')
    })
  })

  describe('fetchCategories', () => {
    it('should fetch categories successfully', async () => {
      // Arrange
      const mockCategories = [
        createMockCategory({
          id: 'cat-1',
          name: 'Main Dishes',
          organization_id: mockOrganizationId,
          sort_order: 0,
        }),
        createMockCategory({
          id: 'cat-2',
          name: 'Desserts',
          organization_id: mockOrganizationId,
          sort_order: 1,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn((table: string) => {
        if (table === 'categories') {
          return createCategoriesQueryBuilder(mockCategories)
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createCategoriesQueryBuilder(data: any[]) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useCategories(mockOrganizationId))

      await act(async () => {
        await result.current.fetchCategories()
      })

      // Assert
      await waitFor(() => {
        expect(result.current.categories).toHaveLength(2)
      })

      expect(result.current.categories[0].name).toBe('Main Dishes')
      expect(result.current.categories[1].name).toBe('Desserts')
      expect(result.current.isLoading).toBe(false)
      expect(result.current.error).toBeNull()
    })

